CREATE TABLE public.root_causes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES public.organisations(id) ON DELETE CASCADE, name text NOT NULL CHECK(length(trim(name)) BETWEEN 1 AND 150), active boolean NOT NULL DEFAULT true, sort_order integer NOT NULL DEFAULT 0, UNIQUE(org_id,id));
GRANT SELECT,INSERT,UPDATE ON public.root_causes TO authenticated;
GRANT ALL ON public.root_causes TO service_role;
ALTER TABLE public.root_causes ENABLE ROW LEVEL SECURITY;
CREATE POLICY root_causes_read ON public.root_causes FOR SELECT TO authenticated USING(public.is_org_member(org_id));
CREATE POLICY root_causes_insert ON public.root_causes FOR INSERT TO authenticated WITH CHECK(public.has_org_role(org_id,ARRAY['org_admin']::public.app_role[]));
CREATE POLICY root_causes_update ON public.root_causes FOR UPDATE TO authenticated USING(public.has_org_role(org_id,ARRAY['org_admin']::public.app_role[])) WITH CHECK(public.has_org_role(org_id,ARRAY['org_admin']::public.app_role[]));
CREATE TRIGGER audit_root_causes AFTER INSERT OR UPDATE OR DELETE ON public.root_causes FOR EACH ROW EXECUTE FUNCTION public.audit_capture();
ALTER TABLE public.complaints ADD COLUMN root_cause_id uuid;
ALTER TABLE public.complaints ADD CONSTRAINT complaint_root_cause_org_fk FOREIGN KEY(org_id,root_cause_id) REFERENCES public.root_causes(org_id,id);
COMMENT ON COLUMN public.complaints.root_cause_category IS 'Legacy free text retained for reporting; managed root_cause_id is required for new closure.';
CREATE FUNCTION public.seed_root_causes() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.root_causes(org_id,name,sort_order) SELECT NEW.id,name,n::integer FROM unnest(ARRAY['Incorrect fees applied','Process not followed','System/technical error','Third-party/partner error','Fraud controls','Communication failure','Policy/product design','Customer error – no firm fault','Other']) WITH ORDINALITY AS t(name,n); RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.seed_root_causes() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER organisation_root_causes AFTER INSERT ON public.organisations FOR EACH ROW EXECUTE FUNCTION public.seed_root_causes();
INSERT INTO public.root_causes(org_id,name,sort_order) SELECT o.id,t.name,t.n::integer FROM public.organisations o CROSS JOIN unnest(ARRAY['Incorrect fees applied','Process not followed','System/technical error','Third-party/partner error','Fraud controls','Communication failure','Policy/product design','Customer error – no firm fault','Other']) WITH ORDINALITY AS t(name,n);
CREATE FUNCTION public.complaint_deadlines(_org uuid,_country text,_product text,_received timestamptz) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.rule_sets; d date:=(_received AT TIME ZONE 'UTC')::date; BEGIN SELECT * INTO r FROM public.rule_sets WHERE org_id=_org AND id=public.resolve_rule_set(_org,_country,_product); IF r.id IS NULL THEN RAISE EXCEPTION 'No deadline rule is configured'; END IF; RETURN jsonb_build_object('rule_set_id',r.id,'ack_due',public.add_business_days(_org,_country,d,r.ack_days),'final_due',public.add_business_days(_org,_country,d,r.final_days),'extended_due',public.add_business_days(_org,_country,d,r.extended_days)); END $$;
REVOKE ALL ON FUNCTION public.complaint_deadlines(uuid,text,text,timestamptz) FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public.complaint_details_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE fields text[]:=ARRAY['complainant_name','complainant_email','complainant_phone','customer_ref','country_code','language','channel','product','category','summary','desired_outcome','vulnerable','received_at']; k text; changed boolean:=false; rc public.root_causes; BEGIN
 IF NEW.status='reopened' AND OLD.status='closed' AND auth.uid() IS NOT NULL AND NOT public.has_org_role(OLD.org_id,ARRAY['org_admin']::public.app_role[]) THEN RAISE EXCEPTION 'Only Org Admins can reopen closed complaints'; END IF;
 FOR k IN SELECT unnest(fields) LOOP IF to_jsonb(NEW)->k IS DISTINCT FROM to_jsonb(OLD)->k THEN changed:=true; END IF; END LOOP;
 IF changed AND auth.uid() IS NOT NULL THEN
 IF OLD.privacy_processing OR OLD.legal_hold OR OLD.anonymised_at IS NOT NULL OR OLD.status='closed' THEN RAISE EXCEPTION 'Complaint details are locked'; END IF;
 IF NOT(public.has_org_role(OLD.org_id,ARRAY['org_admin','complaints_manager']::public.app_role[]) OR (OLD.assigned_to=auth.uid() AND public.has_org_role(OLD.org_id,ARRAY['agent']::public.app_role[]))) THEN RAISE EXCEPTION 'You cannot edit complaint details'; END IF;
 IF current_setting('redress.detail_case',true) IS DISTINCT FROM OLD.id::text OR coalesce(length(trim(current_setting('redress.detail_reason',true))),0) NOT BETWEEN 10 AND 1000 THEN RAISE EXCEPTION 'Use Edit details with a reason of at least 10 characters'; END IF;
 IF NEW.received_at>now() OR EXISTS(SELECT 1 FROM public.letters WHERE org_id=OLD.org_id AND complaint_id=OLD.id AND sent_at<NEW.received_at) THEN RAISE EXCEPTION 'Received date cannot be in the future or after the first letter'; END IF;
 END IF;
 IF NEW.root_cause_id IS DISTINCT FROM OLD.root_cause_id AND NEW.root_cause_id IS NOT NULL THEN
 SELECT * INTO rc FROM public.root_causes WHERE org_id=OLD.org_id AND id=NEW.root_cause_id AND active;
 IF rc.id IS NULL THEN RAISE EXCEPTION 'Choose an active root cause'; END IF;
 NEW.root_cause_category:=rc.name;
 END IF;
 IF NEW.status='closed' AND OLD.status IS DISTINCT FROM 'closed' AND NEW.root_cause_id IS NULL THEN RAISE EXCEPTION 'Choose a managed root cause before closing'; END IF;
 RETURN NEW; END $$;
CREATE TRIGGER complaints_details_guard BEFORE UPDATE ON public.complaints FOR EACH ROW EXECUTE FUNCTION public.complaint_details_guard();
CREATE FUNCTION public.edit_complaint_details(_org uuid,_case uuid,_patch jsonb,_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.complaints; n public.complaints; k text; diff jsonb:='{}'; masked jsonb:='{}'; deadlines jsonb; old_json jsonb; new_json jsonb; keys text[]:=ARRAY['complainant_name','complainant_email','complainant_phone','customer_ref','country_code','language','channel','product','category','summary','desired_outcome','vulnerable','received_at']; BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Not signed in'; END IF;
 IF coalesce(length(trim(_reason)),0) NOT BETWEEN 10 AND 1000 THEN RAISE EXCEPTION 'A reason of at least 10 characters is required'; END IF;
 SELECT * INTO c FROM public.complaints WHERE org_id=_org AND id=_case FOR UPDATE;
 IF c.id IS NULL THEN RAISE EXCEPTION 'Complaint unavailable'; END IF;
 IF c.privacy_processing OR c.legal_hold OR c.anonymised_at IS NOT NULL OR c.status='closed' THEN RAISE EXCEPTION 'Complaint details are locked'; END IF;
 IF NOT(public.has_org_role(_org,ARRAY['org_admin','complaints_manager']::public.app_role[]) OR (c.assigned_to=auth.uid() AND public.has_org_role(_org,ARRAY['agent']::public.app_role[]))) THEN RAISE EXCEPTION 'You cannot edit complaint details'; END IF;
 IF _patch IS NULL OR jsonb_typeof(_patch)<>'object' THEN RAISE EXCEPTION 'Invalid detail fields'; END IF;
 FOR k IN SELECT jsonb_object_keys(_patch) LOOP IF NOT k=ANY(keys) THEN RAISE EXCEPTION 'Invalid detail field: %',k; END IF; END LOOP;
 n:=jsonb_populate_record(c,_patch);
 IF length(trim(n.complainant_name))=0 OR length(trim(n.summary))=0 OR n.country_code IS NULL OR n.language IS NULL OR n.product IS NULL OR n.category IS NULL OR n.channel IS NULL OR n.vulnerable IS NULL OR n.received_at IS NULL THEN RAISE EXCEPTION 'Complete the required complaint details'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.org_countries WHERE org_id=_org AND country_code=n.country_code) THEN RAISE EXCEPTION 'Choose a configured country'; END IF;
 IF n.received_at>now() OR EXISTS(SELECT 1 FROM public.letters WHERE org_id=_org AND complaint_id=_case AND sent_at<n.received_at) THEN RAISE EXCEPTION 'Received date cannot be in the future or after the first letter'; END IF;
 old_json:=to_jsonb(c); new_json:=to_jsonb(n);
 FOR k IN SELECT unnest(keys) LOOP IF old_json->k IS DISTINCT FROM new_json->k THEN diff:=diff||jsonb_build_object(k,jsonb_build_object('old',old_json->k,'new',new_json->k)); masked:=masked||jsonb_build_object(k,jsonb_build_object('old',CASE WHEN k IN ('complainant_email','complainant_phone') AND old_json->k<>'null'::jsonb THEN to_jsonb('[masked]'::text) ELSE old_json->k END,'new',CASE WHEN k IN ('complainant_email','complainant_phone') AND new_json->k<>'null'::jsonb THEN to_jsonb('[masked]'::text) ELSE new_json->k END)); END IF; END LOOP;
 IF diff='{}'::jsonb THEN RETURN; END IF;
 IF n.received_at IS DISTINCT FROM c.received_at OR n.country_code IS DISTINCT FROM c.country_code OR n.product IS DISTINCT FROM c.product THEN deadlines:=public.complaint_deadlines(_org,n.country_code,n.product::text,n.received_at); n:=jsonb_populate_record(n,deadlines); FOR k IN SELECT unnest(ARRAY['rule_set_id','ack_due','final_due','extended_due']) LOOP IF old_json->k IS DISTINCT FROM to_jsonb(n)->k THEN diff:=diff||jsonb_build_object(k,jsonb_build_object('old',old_json->k,'new',to_jsonb(n)->k)); masked:=masked||jsonb_build_object(k,jsonb_build_object('old',old_json->k,'new',to_jsonb(n)->k)); END IF; END LOOP; END IF;
 PERFORM set_config('redress.detail_case',_case::text,true); PERFORM set_config('redress.detail_reason',trim(_reason),true); PERFORM set_config('redress.detail_diff',diff::text,true);
 UPDATE public.complaints SET complainant_name=n.complainant_name,complainant_email=n.complainant_email,complainant_phone=n.complainant_phone,customer_ref=n.customer_ref,country_code=n.country_code,language=n.language,channel=n.channel,product=n.product,category=n.category,summary=n.summary,desired_outcome=n.desired_outcome,vulnerable=n.vulnerable,received_at=n.received_at,rule_set_id=n.rule_set_id,ack_due=n.ack_due,final_due=n.final_due,extended_due=n.extended_due WHERE id=_case AND org_id=_org;
 INSERT INTO public.complaint_events(org_id,complaint_id,actor,kind,detail) VALUES(_org,_case,auth.uid(),'details_edited',jsonb_build_object('reason',trim(_reason),'changes',masked));
 PERFORM set_config('redress.detail_case','',true); PERFORM set_config('redress.detail_reason','',true); PERFORM set_config('redress.detail_diff','',true);
 END $$;
REVOKE ALL ON FUNCTION public.edit_complaint_details(uuid,uuid,jsonb,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.edit_complaint_details(uuid,uuid,jsonb,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.audit_capture() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE o jsonb; n jsonb; org uuid; rid text; changes jsonb; BEGIN IF TG_OP<>'INSERT' THEN o:=to_jsonb(OLD); END IF; IF TG_OP<>'DELETE' THEN n:=to_jsonb(NEW); END IF; IF TG_OP='UPDATE' AND o=n THEN RETURN NEW; END IF; IF TG_TABLE_NAME='organisations' THEN org:=coalesce(n->>'id',o->>'id')::uuid; ELSE org:=coalesce(n->>'org_id',o->>'org_id')::uuid; END IF; rid:=coalesce(n->>'id',o->>'id',n->>'org_id',o->>'org_id'); IF TG_TABLE_NAME='complaints' AND TG_OP='UPDATE' AND current_setting('redress.detail_case',true)=rid THEN changes:=current_setting('redress.detail_diff',true)::jsonb; INSERT INTO public.audit_log(org_id,actor,table_name,row_id,action,before,after) VALUES(org,auth.uid(),TG_TABLE_NAME,rid,'details_edited',jsonb_build_object('values',o,'changes',changes),jsonb_build_object('values',n,'reason',current_setting('redress.detail_reason',true),'changes',changes)); ELSE INSERT INTO public.audit_log(org_id,actor,table_name,row_id,action,before,after) VALUES(org,auth.uid(),TG_TABLE_NAME,rid,lower(TG_OP),public.audit_minimise(TG_TABLE_NAME,o),public.audit_minimise(TG_TABLE_NAME,n)); END IF; RETURN coalesce(NEW,OLD); END $$;
DO $$ DECLARE def text; BEGIN SELECT pg_get_functiondef('public.complaints_log_changes()'::regprocedure) INTO def; def:=replace(def,'BEGIN IF TG_OP=', 'BEGIN IF TG_OP=''UPDATE'' AND current_setting(''redress.detail_case'',true)=NEW.id::text THEN RETURN NEW; END IF; IF TG_OP='); EXECUTE def; END $$;